$ErrorActionPreference = 'Stop'
$siteRoot = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$styleVersion = (Get-FileHash -LiteralPath (Join-Path $siteRoot 'assets/css/styles.css') -Algorithm SHA256).Hash.Substring(0,12).ToLowerInvariant()

function Save-Page([string]$Path, [string]$Content) {
  $target = Join-Path $siteRoot $Path
  $directory = Split-Path $target
  New-Item -ItemType Directory -Force -Path $directory | Out-Null
  [System.IO.File]::WriteAllText($target, $Content, [System.Text.UTF8Encoding]::new($false))
}

function Header([string]$Lang, [string]$Active, [string]$Canonical='/', [string]$Alternate='/fr/') {
  $fr = $Lang -eq 'fr'
  $homeUrl = if ($fr) { '/fr/' } else { '/' }
  $items = if ($fr) {
    @(@('home','Accueil','/fr/'),@('services','Services','/fr/services/'),@('solutions','Solutions','/fr/solutions/'),@('products','Produits','/fr/produits/'),@('tools','Outils','/fr/outils/'),@('sectors','Secteurs','/fr/secteurs/'),@('about','À propos','/fr/a-propos/'),@('contact','Contact','/fr/contact/'))
  } else {
    @(@('home','Home','/'),@('services','Services','/services/'),@('solutions','Solutions','/solutions/'),@('products','Products','/products/'),@('tools','Tools','/tools/'),@('sectors','Sectors','/sectors/'),@('about','About','/about/'),@('contact','Contact','/contact/'))
  }
  $links = ($items | ForEach-Object { $current = if ($_[0] -eq $Active) {' aria-current="page"'} else {''}; '<a href="{0}"{1}>{2}</a>' -f $_[2],$current,$_[1] }) -join ''
  $brandTop = if ($fr) {'Opérations Delta'} else {'Delta Operations'}
  $brandBottom = if ($fr) {'Delta Operations'} else {'Opérations Delta'}
  $menu = if ($fr) {'Menu'} else {'Menu'}
  $activeFr = if ($fr) {' class="active" aria-current="true"'} else {''}
  $activeEn = if (-not $fr) {' class="active" aria-current="true"'} else {''}
  $frUrl = if ($fr) { $Canonical } else { $Alternate }
  $enUrl = if ($fr) { $Alternate } else { $Canonical }
  return @"
<a class="skip" href="#main">$(if($fr){'Aller au contenu'}else{'Skip to content'})</a>
<header class="site-header"><div class="container header-inner">
  <a class="brand" href="$homeUrl"><span class="brand-mark" aria-hidden="true"></span><span><strong>$brandTop</strong><small>$brandBottom</small></span></a>
  <button class="nav-toggle" data-nav-toggle aria-expanded="false" aria-controls="main-nav">$menu</button>
  <nav class="main-nav" id="main-nav" data-nav aria-label="$(if($fr){'Navigation principale'}else{'Main navigation'})">$links</nav>
  <div class="lang-switch" aria-label="$(if($fr){'Langue'}else{'Language'})"><a href="$frUrl" lang="fr"$activeFr>FR</a><a href="$enUrl" lang="en"$activeEn>EN</a></div>
</div></header>
"@
}

