    $services=(MiniCard '/services/#websites' '◇' 'Websites' 'Fast, accessible marketing sites and platforms designed to convert.')+(MiniCard '/services/#web-apps' '▤' 'Web applications' 'Portals, dashboards, and business tools that run in the browser.')+(MiniCard '/services/#mobile-apps' '▯' 'iPhone and Android apps' 'Useful mobile apps for customers, employees, and field teams.')+(MiniCard '/services/#desktop-apps' '▣' 'Desktop applications' 'PC software tailored to your workflow, data, and equipment.')+(MiniCard '/services/#automation' '⚙' 'Automation and AI' 'Integrations, automation, and practical AI where they create real value.')
    $tools=(MiniCard '/tools/workflow-diagnostic/' '⌕' 'Workflow diagnostic' 'Identify friction and wasted time in your processes.')+(MiniCard '/tools/roi-calculator/' '▦' 'Automation ROI calculator' 'Estimate the potential return on your automation project.')+(MiniCard '/tools/sme-express-audit/' '◴' 'SME express audit' 'Get a quick view of your strongest automation opportunities.')+(MiniCard '/tools/requirements-brief-generator/' '▧' 'Requirements brief generator' 'Structure your ideas into a practical working brief.')+(MiniCard '/tools/digital-transformation-checklist/' '☑' 'Digital transformation checklist' 'A step-by-step guide to prepare your digital transformation.')
