Save-Page 'sectors/index.html' (Page 'en' 'Sectors — Delta Operations' 'Custom digital solutions for businesses, nonprofits, teams, and organizations across sectors and locations.' '/sectors/' '/fr/secteurs/' 'sectors' $sectorsEn)
Save-Page 'fr/secteurs/index.html' (Page 'fr' 'Secteurs — Opérations Delta' 'Solutions numériques sur mesure pour entreprises, organismes, équipes et organisations de tous secteurs et de partout.' '/fr/secteurs/' '/sectors/' 'sectors' $sectorsFr)

$aboutEn=(PageHero 'ABOUT' 'Practical digital solutions, wherever you are.' 'Based in Montréal and available worldwide, Delta Operations solves organizational needs with the right mix of design, software, integration, automation, and support.')+'<section class="section"><div class="container"><div class="grid three"><article class="card"><h2>Your goal first</h2><p>We begin with the audience, problem, workflow, and desired result—not a preferred technology.</p></article><article class="card"><h2>Built for the right platform</h2><p>Web, mobile, desktop, or a connected combination is selected according to how and where the solution will be used.</p></article><article class="card"><h2>Custom where useful</h2><p>Existing software is recommended when it fits. Custom development is used when the project genuinely needs it.</p></article><article class="card"><h2>Bilingual and remote</h2><p>Discovery, design, interfaces, documentation, and support can be delivered in French or English to clients anywhere.</p></article><article class="card"><h2>Practical AI</h2><p>AI is one available capability, not the answer to every project. It is added only when the value and limits are clear.</p></article><article class="card"><h2>Long-term quality</h2><p>Accessibility, security, maintainability, performance, and a safe support path are considered from the start.</p></article></div></div></section>'
$aboutFr=(PageHero 'À PROPOS' 'Des solutions numériques pratiques, où que vous soyez.' 'Basée à Montréal et disponible partout dans le monde, Opérations Delta répond aux besoins des organisations avec le bon mélange de design, logiciel, intégration, automatisation et soutien.')+'<section class="section"><div class="container"><div class="grid three"><article class="card"><h2>Votre objectif d&rsquo;abord</h2><p>Nous commençons par le public, le problème, le workflow et le résultat souhaité, pas par une technologie préférée.</p></article><article class="card"><h2>La bonne plateforme</h2><p>Le web, le mobile, l&rsquo;ordinateur ou une combinaison connectée est choisi selon la façon et l&rsquo;endroit où la solution sera utilisée.</p></article><article class="card"><h2>Sur mesure lorsque pertinent</h2><p>Un logiciel existant est recommandé lorsqu&rsquo;il convient. Le développement sur mesure répond aux projets qui l&rsquo;exigent réellement.</p></article><article class="card"><h2>Bilingue et à distance</h2><p>Découverte, design, interfaces, documentation et soutien peuvent être livrés en français ou en anglais, partout dans le monde.</p></article><article class="card"><h2>IA pratique</h2><p>L&rsquo;IA est une capacité parmi d&rsquo;autres, pas la réponse à chaque projet. Elle est ajoutée seulement lorsque sa valeur et ses limites sont claires.</p></article><article class="card"><h2>Qualité à long terme</h2><p>Accessibilité, sécurité, maintenance, performance et soutien sont considérés dès le départ.</p></article></div></div></section>'
